請寫出執行下列 Java 程式碼的輸出結果。（15 分）
①public class Testa {public static void main(String[ ] args) {int [ ] a = {1, 2, 3, 4};swap( a );System.out.println( "a [0] = " + a [0] );}public static void swap(int [ ] data) {int temp = data[0];data[0] = data [ data.length – 1 ];data [ data.length – 1 ] = temp;}}
②public class Testb{public static void main(String[ ] args) {T t = new T ( );swap( t );System.out.println( " e1 = " + t.e1 + ", e2 = " + t.e2);}public static void swap(T t) {int temp = t.e1;t.e1 = t.e2;t.e2 = temp;}}class T {int e1 = 1 ;int e2 = 2 ;}
③public class Testb{public static void main(String[ ] args) {T t = new T ( );swap( t.e1, t.e2 );System.out.println( " e1 = " + t.e1 + ", e2 = " + t.e2);}public static void swap(int e1, int e2) {int temp = e1;e1 = e2;e2 = temp;}}class T {int e1 = 1 ;int e2 = 2 ;}
